import json
p='.post/PRE.raw.jsonl'
for i,l in enumerate(open(p,encoding='utf-8')):
    try:
        d=json.loads(l)
    except Exception as e:
        print(i,'PARSE_ERR',e, l[:200]); continue
    t=d.get('type')
    if t=='item.completed':
        it=d.get('item',{})
        txt=it.get('text') or it.get('command') or ''
        if it.get('command'):
            txt=it.get('command')
        print(i,t,it.get('type'),repr(txt[:200]))
    elif t=='item.started':
        it=d.get('item',{})
        print(i,t,it.get('type'),repr((it.get('command') or '')[:160]))
    else:
        print(i,t,repr(str(d)[:300]))
EOF

